import unicodedata
import hashlib
import hmac
import os
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = ':memory:'
SECRET_KEY = os.urandom(32)

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
        _init_db(g.db)
    return g.db

def _init_db(db):
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'user'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS resources (
        id INTEGER PRIMARY KEY,
        owner TEXT NOT NULL,
        content TEXT NOT NULL,
        is_private INTEGER DEFAULT 1
    )''')
    # Seed admin
    admin_hash = _hash_password('supersecret')
    db.execute('INSERT OR IGNORE INTO users (username, password_hash, role) VALUES (?, ?, ?)',
               ('admin', admin_hash, 'admin'))
    db.execute('INSERT OR IGNORE INTO resources (owner, content, is_private) VALUES (?, ?, ?)',
               ('admin', 'SECRET_API_KEY=sk-prod-98xj2m', 1))
    db.commit()

def _hash_password(password):
    salt = hashlib.sha256(b'fixed-salt-for-demo').hexdigest()[:16]
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex()

def _generate_token(username):
    payload = f"{username}:{os.urandom(8).hex()}"
    sig = hmac.new(SECRET_KEY, payload.encode(), 'sha256').hexdigest()
    return f"{payload}:{sig}"

def _verify_token(token):
    try:
        parts = token.rsplit(':', 1)
        if len(parts) != 2:
            return None
        payload, sig = parts
        expected = hmac.new(SECRET_KEY, payload.encode(), 'sha256').hexdigest()
        if hmac.compare_digest(sig, expected):
            username = payload.split(':')[0]
            return username
        return None
    except Exception:
        return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.headers.get('Authorization', '')
        if not auth.startswith('Bearer '):
            return jsonify({'error': 'unauthorized'}), 401
        token = auth[7:]
        username = _verify_token(token)
        if not username:
            return jsonify({'error': 'invalid token'}), 401
        g.current_user = username
        return f(*args, **kwargs)
    return decorated

def _sanitize_username(raw_username):
    """Sanitize username: strip whitespace, enforce length limits."""
    username = raw_username.strip()
    if len(username) < 1 or len(username) > 64:
        return None
    # Only allow printable characters
    if not all(c.isprintable() for c in username):
        return None
    return username

def _check_reserved_names(username):
    """Prevent registration of reserved usernames."""
    reserved = ['admin', 'root', 'system', 'administrator']
    # Check against reserved list
    if username.lower() in reserved:
        return False
    return True

def _normalize_for_lookup(username):
    """Normalize username for database lookup to handle Unicode equivalences."""
    return unicodedata.normalize('NFKC', username).lower()

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing fields'}), 400

    raw_username = data['username']
    username = _sanitize_username(raw_username)
    if not username:
        return jsonify({'error': 'invalid username'}), 400

    # Check reserved names against the raw sanitized input
    if not _check_reserved_names(username):
        return jsonify({'error': 'reserved username'}), 403

    password_hash = _hash_password(data['password'])
    db = get_db()

    try:
        # Store the username as-provided (after sanitization)
        db.execute('INSERT INTO users (username, password_hash, role) VALUES (?, ?, ?)',
                   (username, password_hash, 'user'))
        db.commit()
        return jsonify({'message': 'registered', 'username': username}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username taken'}), 409

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing fields'}), 400

    username = data['username'].strip()
    # Normalize for lookup to handle Unicode equivalences
    normalized = _normalize_for_lookup(username)
    password_hash = _hash_password(data['password'])

    db = get_db()
    # Look up by normalized form
    rows = db.execute('SELECT username, password_hash, role FROM users').fetchall()
    for row in rows:
        if _normalize_for_lookup(row['username']) == normalized:
            if row['password_hash'] == password_hash:
                token = _generate_token(row['username'])
                return jsonify({'token': token, 'role': row['role']}), 200

    return jsonify({'error': 'invalid credentials'}), 401

@app.route('/resources', methods=['GET'])
@require_auth
def get_resources():
    db = get_db()
    username = g.current_user

    # Authorization: users can only see their own resources
    # Admin can see all resources
    user_row = db.execute('SELECT role FROM users WHERE username = ?', (username,)).fetchone()

    if user_row and user_row['role'] == 'admin':
        rows = db.execute('SELECT * FROM resources').fetchall()
    else:
        rows = db.execute('SELECT * FROM resources WHERE owner = ? AND is_private = 0',
                         (username,)).fetchall()

    return jsonify({'resources': [dict(r) for r in rows]}), 200

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    app.run(debug=False)
